#include <iostream>
#include <utility>
class UniqueInt {
public:
    explicit UniqueInt(int value) : ptr_(new int(value)) {}
    ~UniqueInt() { delete ptr_; }
    UniqueInt(const UniqueInt&) = delete;
    UniqueInt& operator=(const UniqueInt&) = delete;
    UniqueInt(UniqueInt&& other) noexcept : ptr_(std::exchange(other.ptr_, nullptr)) {}
    UniqueInt& operator=(UniqueInt&& other) noexcept {
        if (this != &other) { delete ptr_; ptr_ = std::exchange(other.ptr_, nullptr); }
        return *this;
    }
    int& operator*() { return *ptr_; }
private: int* ptr_;
};
int main() { UniqueInt a{7}; UniqueInt b{std::move(a)}; std::cout << *b << '\n'; }
